INSERT INTO `{#}controllers` (`title`, `name`, `is_enabled`, `options`, `author`, `url`, `version`, `is_backend`) VALUES
('Конструктор тем', 'inthemer', 1, '', 'InstantSoft', 'http://www.instantcms.ru', '2.0.6', 1);

CREATE TABLE `{#}inthemer_images` (
  `id` int(11) NOT NULL,
  `title` varchar(255) DEFAULT NULL,
  `path` varchar(1024) DEFAULT NULL,
  `is_pattern` tinyint(4) UNSIGNED DEFAULT '0'
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

INSERT INTO `{#}inthemer_images` (`id`, `title`, `path`, `is_pattern`) VALUES
(1, 'InstantCMS Logo', 'inthemer/logo.png', 0),
(2, 'Background', 'inthemer/background.jpg', 0);

CREATE TABLE `{#}inthemer_layouts` (
  `id` int(10) UNSIGNED NOT NULL,
  `date_pub` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `is_enabled` tinyint(1) UNSIGNED DEFAULT NULL,
  `name` varchar(255) DEFAULT NULL,
  `title` varchar(255) DEFAULT NULL,
  `blocks` longtext,
  `options` longtext,
  `data_sources` longtext,
  `selectors` longtext,
  `scope` int(11) DEFAULT '0',
  `mask_pos` text,
  `mask_neg` text,
  `code_head` text,
  `code_body` text,
  `access` text
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

