CREATE TABLE `{#}inthemer_library` (
  `id` int(11) NOT NULL,
  `title` varchar(256) DEFAULT NULL,
  `name` varchar(128) DEFAULT NULL,
  `version` int(11) DEFAULT '1',
  `blocks` longtext
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

CREATE TABLE `{#}inthemer_presets` (
  `id` int(10) UNSIGNED NOT NULL,
  `title` varchar(255) DEFAULT NULL,
  `block_name` varchar(100) DEFAULT NULL,
  `selectors` longtext
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

ALTER TABLE `{#}inthemer_images` ADD PRIMARY KEY (`id`), ADD KEY `premade` (`is_pattern`);
ALTER TABLE `{#}inthemer_layouts` ADD PRIMARY KEY (`id`);
ALTER TABLE `{#}inthemer_library` ADD PRIMARY KEY (`id`);
ALTER TABLE `{#}inthemer_presets` ADD PRIMARY KEY (`id`), ADD KEY `block_name` (`block_name`);
ALTER TABLE `{#}inthemer_images` MODIFY `id` int(11) NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=3;
ALTER TABLE `{#}inthemer_layouts` MODIFY `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=33;
ALTER TABLE `{#}inthemer_library` MODIFY `id` int(11) NOT NULL AUTO_INCREMENT;
ALTER TABLE `{#}inthemer_presets` MODIFY `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT;

CREATE TABLE `{#}inthemer_layout_revs` (
  `id` int(10) UNSIGNED NOT NULL,
  `layout_id` int(11) DEFAULT NULL,
  `no` int(11) DEFAULT NULL,
  `date_pub` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `blocks` longtext,
  `options` longtext,
  `data_sources` longtext,
  `selectors` longtext,
  `code_head` text,
  `code_body` text
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

ALTER TABLE `{#}inthemer_layout_revs`
  ADD PRIMARY KEY (`id`),
  ADD KEY `layout_id` (`layout_id`),
  ADD KEY `no` (`no`);

ALTER TABLE `{#}inthemer_layout_revs`
  MODIFY `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT;

ALTER TABLE `{#}inthemer_layouts` ADD `rev_no` INT NULL DEFAULT '0' AFTER `id`;

UPDATE `{#}inthemer_layouts` SET rev_no = 1;

CREATE TABLE `{#}inthemer_opt_dumps` (
  `layout_id` int(11) DEFAULT NULL,
  `options` longtext
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

ALTER TABLE `{#}inthemer_opt_dumps` ADD KEY `layout_id` (`layout_id`);

ALTER TABLE `{#}inthemer_library` ADD `is_global` TINYINT NULL DEFAULT '0' AFTER `blocks`, ADD INDEX (`is_global`);
